/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trigger_institution_student_absence_details_insert` AFTER INSERT ON `institution_student_absence_details` FOR EACH ROW BEGIN UPDATE summary_area_institution_grade_attendances SET summary_area_institution_grade_attendances.present_female_count = CASE WHEN NEW.absence_type_id != 3 AND( SELECT COUNT(*) absence_counter FROM ( SELECT institution_student_absence_details.academic_period_id ,institution_student_absence_details.institution_id ,institution_student_absence_details.education_grade_id ,institution_student_absence_details.institution_class_id ,institution_student_absence_details.student_id ,institution_student_absence_details.date absence_date ,institution_student_absence_details.subject_id ,period_counter.attendance_per_day period_attendance_per_day ,subject_counter.subjects_taken ,attendance_type.value FROM institution_student_absence_details INNER JOIN security_users ON security_users.id = institution_student_absence_details.student_id INNER JOIN academic_periods ON academic_periods.id = institution_student_absence_details.academic_period_id INNER JOIN ( SELECT student_mark_type_status_grades.education_grade_id ,student_mark_type_statuses.academic_period_id ,student_attendance_mark_types.attendance_per_day FROM student_mark_type_status_grades INNER JOIN student_mark_type_statuses ON student_mark_type_statuses.id = student_mark_type_status_grades.student_mark_type_status_id INNER JOIN student_attendance_mark_types ON student_attendance_mark_types.id = student_mark_type_statuses.student_attendance_mark_type_id INNER JOIN academic_periods ON academic_periods.id = student_mark_type_statuses.academic_period_id WHERE academic_periods.id = NEW.academic_period_id AND student_mark_type_status_grades.education_grade_id = NEW.education_grade_id GROUP BY student_mark_type_status_grades.education_grade_id ,student_mark_type_statuses.academic_period_id) period_counter ON period_counter.education_grade_id = in