/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trigger_student_attendance_marked_records_insert` AFTER INSERT ON `student_attendance_marked_records` FOR EACH ROW BEGIN UPDATE summary_area_institution_grade_attendances INNER JOIN( SELECT COUNT(DISTINCT(attendance_details.institution_class_id)) marked_classes_counter ,SUM(class_counter.present_female_count) present_female_count ,SUM(class_counter.present_male_count) present_male_count FROM ( SELECT student_attendance_marked_records.academic_period_id ,student_attendance_marked_records.institution_id ,student_attendance_marked_records.education_grade_id ,student_attendance_marked_records.institution_class_id FROM student_attendance_marked_records WHERE student_attendance_marked_records.academic_period_id = NEW.academic_period_id AND student_attendance_marked_records.institution_id = NEW.institution_id AND student_attendance_marked_records.education_grade_id = NEW.education_grade_id AND student_attendance_marked_records.date = NEW.date AND student_attendance_marked_records.no_scheduled_class != 1 GROUP BY student_attendance_marked_records.academic_period_id ,student_attendance_marked_records.institution_id ,student_attendance_marked_records.education_grade_id ,student_attendance_marked_records.institution_class_id) attendance_details INNER JOIN ( SELECT institution_class_students.education_grade_id ,institution_class_students.institution_id ,institution_class_students.academic_period_id ,institution_class_students.institution_class_id ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 1 THEN institution_class_students.student_id END)) present_male_count ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 2 THEN institution_class_students.student_id END)) present_female_count FROM institution_class_students INNER JOIN security_users ON security_users.id = institution_class_students.student_id INNER JOIN academic_periods ON academic_periods.id = institution_class_students.academic_period_id WHERE academic_periods.id = NEW.academic_period_id AND institution_class_students.institution_id = NEW.institution_id AND institution_class_students.education_grade_id = NEW.education_grade_id AND institution_class_students.student_status_id = 1 GROUP BY institution_class_students.education_grade_id ,institution_class_students.institution_id ,institution_class_students.academic_period_id ,institution_class_students.institution_class_id ) class_counter ON class_counter.education_grade_id = attendance_details.education_grade_id AND class_counter.institution_id = attendance_details.institution_id AND class_counter.institution_class_id = attendance_details.institution_class_id AND class_counter.academic_period_id = attendance_details.academic_period_id GROUP BY attendance_details.academic_period_id ,attendance_details.institution_id ,attendance_details.education_grade_id ) attendance_info SET summary_area_institution_grade_attendances.present_female_count = CASE WHEN attendance_info.present_female_count > summary_area_institution_grade_attendances.present_female_count THEN attendance_info.present_female_count - summary_area_institution_grade_attendances.absent_female_count ELSE summary_area_institution_grade_attendances.present_female_count END ,summary_area_institution_grade_attendances.present_male_count = CASE WHEN attendance_info.present_male_count > summary_area_institution_grade_attendances.present_male_count THEN attendance_info.present_male_count - summary_area_institution_grade_attendances.absent_male_count ELSE summary_area_institution_grade_attendances.present_male_count END ,summary_area_institution_grade_attendances.marked_classes = CASE WHEN attendance_info.marked_classes_counter > summary_area_institution_grade_attendances.marked_classes THEN attendance_info.marked_classes_counter ELSE summary_area_institution_grade_attendances.marked_classes END WHERE summary_area_institution_grade_attendances.attendance_date = NEW.date AND summary_area_institution_grade_attendances.institution_id = NEW.institution_id AND summary_area_institution_grade_attendances.education_grade_id = NEW.education_grade_id AND summary_area_institution_grade_attendances.academic_period_id = NEW.academic_period_id; END */;;
